#include <iostream>
#include <string>
#include <string_view>

namespace library {
    inline constexpr int shelf_capacity{3};
}
namespace library::labels {
    inline std::string describe(std::string_view name)
    {
        return std::string{name} + ": " + std::to_string(shelf_capacity) + " places";
    }
}

int main()
{
    namespace labels = library::labels;
    std::cout << labels::describe("Science") << '\n';
}
